from decimal import Decimal


def money(value):
    return Decimal(str(value))


def price_order(lines):
    return sum((money(line["unit_price"]) * line["quantity"] for line in lines), Decimal("0"))

import unittest
from decimal import Decimal
from src.pricing import money, price_order

class PricingTests(unittest.TestCase):
    def test_standard_is_unchanged(self):
        lines = [{"unit_price": "12.50", "quantity": 2}]
        self.assertEqual(price_order(lines), Decimal("25.00"))
        self.assertEqual(money("1.20"), Decimal("1.20"))

    def test_gold(self):
        self.assertEqual(price_order([{"unit_price": "10.00", "quantity": 2}], "gold"), Decimal("18.00"))

