import copy

def migrate(config, installed_model_ids):
    result = copy.deepcopy(config)
    profiles = result.setdefault("profiles", {})
    defaults = {
        "sd15-smoke": {"model_id": "sd15", "managed_by": "legacy-auto"},
        "old-coder": {"model_id": "coder-v1", "managed_by": "legacy-auto"},
    }
    for name, value in defaults.items():
        profiles.setdefault(name, value)
    return result

import unittest
from src.migrate import migrate

class MigrationTests(unittest.TestCase):
    def test_keeps_installed_generated_profile(self):
        cfg={"profiles":{"auto":{"model_id":"m1","managed_by":"legacy-auto"}}}
        self.assertIn("auto",migrate(cfg,{"m1"})["profiles"] )
    def test_removes_missing_generated_profile(self):
        cfg={"profiles":{"auto":{"model_id":"gone","managed_by":"legacy-auto"}}}
        self.assertNotIn("auto",migrate(cfg,set())["profiles"] )

